namespace ID_Indetails.api.Models;

public class LabourWeekDay
{
    public long Id { get; set; }

    public long LabourWeekId { get; set; }

    public DateOnly WorkDate { get; set; }

    public int Workers { get; set; }

    public decimal DailyPay { get; set; }

    /// <summary>Generated by MySQL as workers × daily pay; never written by the app.</summary>
    public decimal Cost { get; private set; }

    public LabourWeek LabourWeek { get; set; } = null!;
}
